const CACHE='detention-overseer-20';
export function setupInstall({show,busy,toast}){
 let prompt=null,downloading=false;
 const installed=()=>matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
 window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();prompt=event;});
 window.addEventListener('appinstalled',()=>{prompt=null;toast('Detention is on your Home Screen. He has moved in.');});
 if('serviceWorker'in navigator&&isSecureContext)navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});
 document.querySelector('#install-open').onclick=async()=>{
 if(busy()){toast('Finish your class first. Your instructor is still watching.');return;}
 const apple=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 show(`<span class="eyebrow">YOUR VERY SMALL SUPERVISOR</span><h2>${installed()?'He lives here now.':'Take Detention with you.'}</h2><p>${installed()?'You’re running the Home Screen app.':apple?'Open this page in Safari, then:':'Add Detention to your device for its own app window.'}</p>${!installed()&&apple?'<ol class="install-steps"><li>Tap <b>Share</b> in Safari (the square with an upward arrow).</li><li>Choose <b>Add to Home Screen</b>.</li><li>Keep <b>Open as Web App</b> on if shown, then tap <b>Add</b>.</li></ol>':!installed()?'<button class="primary" id="native-install">Install Detention</button><p class="note">If no install prompt appears, use your browser menu’s Install app or Add to Home Screen option.</p>':''}<p class="note">No App Store account needed. Keep the app open during focus; leaving still pauses class. Your progress stays in this browser or installed app—it does not sync between devices.</p><div class="offline-pack"><h3>Take the cast offline.</h3><p>Save the characters and camera tools to this device. The download is optional.</p><button class="secondary" id="offline-save" disabled>Checking download size…</button><progress id="offline-progress" value="0" max="1" hidden aria-label="Offline download progress"></progress><p id="offline-status" role="status" class="note"></p></div>`);
 const install=document.querySelector('#native-install');if(install)install.onclick=async()=>{if(prompt){const event=prompt;prompt=null;await event.prompt();await event.userChoice;}else toast('Use your browser menu to install or add to Home Screen.');};
 const button=document.querySelector('#offline-save'),status=document.querySelector('#offline-status'),progress=document.querySelector('#offline-progress');
 if(!('caches'in window)||!('serviceWorker'in navigator)||!isSecureContext){button.textContent='Offline mode needs a secure connection';status.textContent='Open the published HTTPS website to save it for offline use.';return;}
 try{const response=await fetch('./offline-pack.json');if(!response.ok)throw Error();const pack=await response.json();button.disabled=downloading;button.textContent=downloading?'Download in progress…':`Save offline · ${Math.ceil(pack.bytes/1024/1024)} MB`;button.onclick=async()=>{if(downloading)return;downloading=true;button.disabled=true;progress.hidden=false;progress.max=pack.files.length;try{const registration=await navigator.serviceWorker.getRegistration();if(!registration)throw Error('Offline setup is unavailable. Reload online and try again.');const cache=await caches.open(CACHE);for(let i=0;i<pack.files.length;i++){const url=new URL(pack.files[i],location.href);const response=await fetch(url,{cache:'reload'});if(!response.ok)throw Error('Download interrupted. Reconnect and retry.');await cache.put(url.href,response);progress.value=i+1;status.textContent=`Saving ${i+1} of ${pack.files.length} files…`;}button.textContent='Saved for offline use';status.textContent='Download complete. Close all Detention tabs and reopen once to activate offline support. Your device may remove saved files if storage runs low.';}catch(error){button.disabled=false;button.textContent='Retry offline download';status.textContent=error.message||'Not enough storage, or connection lost. Try again online.';}finally{downloading=false;}};}catch{button.textContent='Download unavailable';status.textContent='Reconnect and open this panel again.';}
 };
}
